# -*- coding: utf-8 -*-
"""
Генератор файла ручных тест-кейсов qa-docs/07-test-cases.xlsx.

Запуск:  python generate_test_cases.py

Структура книги повторяет образец manzil-testcases-full.xlsx:
«Сводка» → отдельные функциональные листы с 10 одинаковыми колонками.

Важно: при перегенерации скрипт НЕ затирает «Комментарий» и «Статус»,
заполненные при ручном прогоне. При переходе со старого формата значение
«Фактического результата» также переносится в «Комментарий».

Данные кейсов лежат ниже в списке MODULES — модули добавляются волнами,
скрипт каждый раз пересобирает файл целиком.
"""

import re
