# ---------------------------------------------------------------------------
# ДАННЫЕ ТЕСТ-КЕЙСОВ
#
# Поля кейса: id, title (краткое), desc (полное), pre (предусловия),
# steps (список шагов — нумерация проставится сама), priority, ctype
# (Позитивный/Негативный/Граничный), expected.
#
# Названия кнопок и полей взяты из кода фронтенда project/admin
# (файлы переводов src/locales/ru и src/locales/uz и компоненты экранов).
# Интерфейс двуязычный: в кейсах — русские названия, в скобках узбекские,
# если надпись на экране может быть на узбекском.
# ---------------------------------------------------------------------------

