# ---------------------------------------------------------------------------
# Генерация
# ---------------------------------------------------------------------------

PRIORITY_COL = "H"
STATUS_COL = "I"
DEFAULT_STATUS = "Not Run"
DEFAULT_METHOD = "UI"

TYPE_TAGS = {
    "Позитивный": "positive",
    "Негативный": "negative",
    "Граничный": "boundary",
    "Интеграционный": "integration",
    "Безопасность": "security",
    "Восстановление": "recovery",
    "Гонка": "concurrency",
    "Доступность": "a11y",
    "Конфликт данных": "conflict",
    "Нагрузочный": "load",
    "Регрессионный": "regression",
    "Сквозной": "e2e",
    "Совместимость": "compatibility",
}
METHOD_TAGS = {
    "UI": ("web",),
    "API": ("api",),
    "UI+API": ("web", "api"),
}
ROUTE_PATTERN = re.compile(
    r"(?<![A-Za-zА-Яа-яЁё0-9_])/"
    r"(?:[A-Za-zА-Яа-яЁё0-9_{}.:*-]+)"
    r"(?:/[A-Za-zА-Яа-яЁё0-9_{}.:*?=-]+)*"
)
IGNORED_ROUTES = {"/oy"}  # часть подписи «сум/oy», а не адрес экрана/API


def module_meta(module) -> dict:
    """Возвращает описание листа для сводки и повторяемых полей кейса."""
    return MODULE_META.get(
        module["sheet"],
        {
            "section": module["sheet"],
            "area": module["sheet"],
            "coverage": module["sheet"],
        },
    )


def module_layer(module) -> str:
    """Переводит способы проверки кейсов в слой, как в файле-образце."""
    methods = {case.get("method", DEFAULT_METHOD) for case in module["cases"]}
    has_web = bool(methods & {"UI", "UI+API"})
    has_api = bool(methods & {"API", "UI+API"})
    if has_web and has_api:
        return "WEB/API"
    return "WEB" if has_web else "API"


def infer_area(case, module) -> str:
    """Находит маршрут в тексте кейса; иначе берёт подраздел модуля."""
    explicit_area = case.get("area")
    if explicit_area:
        return explicit_area

    searchable = "\n".join(
        [
            case.get("title", ""),
            case.get("desc", ""),
            case.get("pre", ""),
            *case.get("steps", []),
            case.get("expected", ""),
        ]
    )
    routes = []
    for route in ROUTE_PATTERN.findall(searchable):
        route = route.rstrip(".,;:!?)]'\"`")
        if route and route not in IGNORED_ROUTES and route not in routes:
            routes.append(route)
        if len(routes) == 3:
            break
    return " · ".join(routes) if routes else module_meta(module)["area"]


def default_comment(case) -> str:
    """Формирует компактные теги в стиле файла-образца."""
    tags = list(METHOD_TAGS.get(case.get("method", DEFAULT_METHOD), ("web",)))
    type_tag = TYPE_TAGS.get(case.get("ctype"), str(case.get("ctype", "")).lower())
    if type_tag and type_tag not in tags:
        tags.append(type_tag)
    return "|".join(tags)


def read_existing_results(path: Path) -> dict:
    """Вычитывает из существующего файла заполненные вручную колонки.

    Колонки ищутся по заголовкам (а не по буквам), поэтому сохранение
    работает, даже если состав колонок между версиями скрипта менялся.
    Поддерживает новый формат («Комментарий») и старый
    («Фактический результат», «Автоматизация»).
    """
    results: dict[str, dict] = {}
    if not path.exists():
        return results
    wb = openpyxl.load_workbook(path, read_only=True, data_only=False)
    for ws in wb.worksheets:
        if ws.title in (SUMMARY_SHEET, PROGRESS_SHEET):
            continue
        header = next(ws.iter_rows(min_row=1, max_row=1, values_only=True), None)
        if not header:
            continue
        if "ID" not in header or "Статус" not in header:
            continue
        id_idx = header.index("ID")
        status_idx = header.index("Статус")
        comment_idx = header.index("Комментарий") if "Комментарий" in header else None
        fact_idx = (
            header.index("Фактический результат")
            if "Фактический результат" in header
            else None
        )
        automation_idx = (
            header.index("Автоматизация") if "Автоматизация" in header else None
        )
        for row in ws.iter_rows(min_row=2, values_only=True):
            if not row or len(row) <= id_idx or not row[id_idx]:
                continue
            case_id = str(row[id_idx]).strip()
            if not case_id.startswith("TC-"):
                continue
            comment = (
                row[comment_idx]
                if comment_idx is not None and len(row) > comment_idx
                else None
            )
            fact = (
                row[fact_idx] if fact_idx is not None and len(row) > fact_idx else None
            )
            status = row[status_idx] if len(row) > status_idx else None
            automation = (
                row[automation_idx]
                if automation_idx is not None and len(row) > automation_idx
                else None
            )
            results[case_id] = {
                "comment": comment,
                "fact": fact,
                "status": status,
                "automation": automation,
            }
    wb.close()
    return results


def build_module_sheet(wb, module, preserved):
    ws = wb.create_sheet(module["sheet"])
    meta = module_meta(module)

    # Заголовки
    for col_idx, (header, width) in enumerate(COLUMNS, start=1):
        cell = ws.cell(row=1, column=col_idx, value=header)
        cell.font = HEADER_FONT
        cell.fill = HEADER_FILL
        cell.border = THIN_BORDER
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
        ws.column_dimensions[get_column_letter(col_idx)].width = width
    ws.row_dimensions[1].height = 28

    wrap = Alignment(vertical="top", wrap_text=True)
    center = Alignment(horizontal="center", vertical="center", wrap_text=True)

    for row_idx, case in enumerate(module["cases"], start=2):
        steps_text = "\n".join(f"{i}. {s}" for i, s in enumerate(case["steps"], start=1))
        saved = preserved.get(case["id"], {})
        status_saved = saved.get("status")
        comment_saved = saved.get("comment")
        comment = str(comment_saved).strip() if comment_saved not in (None, "") else ""
        if not comment:
            comment = default_comment(case)
            fact_saved = saved.get("fact")
            if fact_saved not in (None, ""):
                comment += f"\nФактический результат: {fact_saved}"
            automation_saved = saved.get("automation")
            if automation_saved not in (None, "", "—"):
                comment += f"\nАвтоматизация: {automation_saved}"

        scenario = f"{case['title']}\n\n{case['desc']}"

        values = [
            case["id"],
            meta["section"],
            infer_area(case, module),
            scenario,
            case["pre"],
            steps_text,
            case["expected"],
            case["priority"],
            status_saved or case.get("status", DEFAULT_STATUS),
            comment,
        ]
        for col_idx, value in enumerate(values, start=1):
            cell = ws.cell(row=row_idx, column=col_idx, value=value)
            cell.border = THIN_BORDER
            if col_idx in (1, 8, 9):  # ID, Приоритет, Статус
                cell.alignment = center
            else:
                cell.alignment = wrap

        priority_cell = ws.cell(row=row_idx, column=8)
        priority_bg, priority_fg = PRIORITY_COLORS[case["priority"]]
        priority_cell.fill = PatternFill("solid", fgColor=priority_bg)
        priority_cell.font = Font(
            color=priority_fg,
            bold=(case["priority"] == "Critical"),
        )

        # Примерная высота строки: по самой «высокой» ячейке
        def est_lines(text, width_chars):
            lines = 0
            for part in str(text).split("\n"):
                lines += max(1, (len(part) // width_chars) + 1)
            return lines

        n_lines = max(
            est_lines(steps_text, 50),
            est_lines(scenario, 40),
            est_lines(case["expected"], 54),
            est_lines(case["pre"], 32),
        )
        ws.row_dimensions[row_idx].height = min(max(n_lines * 13.2 + 4, 30), 300)

    last_row = len(module["cases"]) + 1

    # Выпадающие списки (с запасом на 30 строк ниже — если кейсы добавятся руками)
    dv_priority = DataValidation(type="list", formula1=PRIORITY_LIST, allow_blank=True)
    dv_priority.error = "Выбери значение из списка: Critical, High, Medium, Low"
    dv_priority.errorTitle = "Недопустимое значение"
    ws.add_data_validation(dv_priority)
    dv_priority.add(f"{PRIORITY_COL}2:{PRIORITY_COL}{last_row + 30}")

    dv_status = DataValidation(type="list", formula1=STATUS_LIST, allow_blank=True)
    dv_status.error = "Выбери значение из списка: Not Run, Passed, Failed, Blocked"
    dv_status.errorTitle = "Недопустимое значение"
    ws.add_data_validation(dv_status)
    dv_status.add(f"{STATUS_COL}2:{STATUS_COL}{last_row + 30}")

    # Условное форматирование статуса
    status_range = f"{STATUS_COL}2:{STATUS_COL}{last_row + 30}"
    for status, (bg, fg) in STATUS_COLORS.items():
        ws.conditional_formatting.add(
            status_range,
            CellIsRule(
                operator="equal",
                formula=[f'"{status}"'],
                fill=PatternFill("solid", fgColor=bg),
                font=Font(color=fg, bold=(status in ("Passed", "Failed"))),
            ),
        )

    # Закрепление шапки и автофильтр
    ws.freeze_panes = "A2"
    ws.auto_filter.ref = f"A1:{get_column_letter(len(COLUMNS))}{last_row}"

    return ws


def build_summary(wb):
    """Создаёт первый лист-каталог в структуре файла-образца."""
    ws = wb.create_sheet(SUMMARY_SHEET, 0)

    widths = {"A": 34, "B": 26, "C": 80, "D": 12, "E": 10}
    for column, width in widths.items():
        ws.column_dimensions[column].width = width

    headers = ["Раздел", "Лист", "Маршруты / охват", "Слой", "Кейсов"]
    for col_idx, header in enumerate(headers, start=1):
        cell = ws.cell(row=1, column=col_idx, value=header)
        cell.font = HEADER_FONT
        cell.fill = HEADER_FILL
        cell.border = THIN_BORDER
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
    ws.row_dimensions[1].height = 28

    wrap = Alignment(vertical="top", wrap_text=True)
    center = Alignment(horizontal="center", vertical="center", wrap_text=True)
    for row_idx, module in enumerate(MODULES, start=2):
        meta = module_meta(module)
        values = [
            meta["section"],
            module["sheet"],
            meta["coverage"],
            module_layer(module),
            len(module["cases"]),
        ]
        for col_idx, value in enumerate(values, start=1):
            cell = ws.cell(row=row_idx, column=col_idx, value=value)
            cell.border = THIN_BORDER
            cell.alignment = center if col_idx in (4, 5) else wrap

    total_row = len(MODULES) + 2
    layer_counts = Counter(
        case.get("method", DEFAULT_METHOD)
        for module in MODULES
        for case in module["cases"]
    )
    total_values = [
        "ИТОГО",
        "",
        (
            f"API {layer_counts['API']} · Web {layer_counts['UI']} · "
            f"Web+API {layer_counts['UI+API']}"
        ),
        "",
        sum(len(module["cases"]) for module in MODULES),
    ]
    for col_idx, value in enumerate(total_values, start=1):
        cell = ws.cell(row=total_row, column=col_idx, value=value)
        cell.border = THIN_BORDER
        cell.font = Font(bold=True)
        cell.alignment = center if col_idx in (4, 5) else wrap
        if col_idx in (1, 5):
            cell.fill = TOTAL_FILL

    ws.freeze_panes = "A2"
    ws.auto_filter.ref = f"A1:E{total_row}"
    ws.sheet_properties.tabColor = "1F4E78"
    return ws


def build_progress_sheet(wb):
    """Сохраняет рабочую статистику, риски и Release Gate отдельно от каталога."""
    ws = wb.create_sheet(PROGRESS_SHEET, 1)

    ws.column_dimensions["A"].width = 34
    for col in "BCDEFG":
        ws.column_dimensions[col].width = 12

    title = ws.cell(row=1, column=1, value="Operator AI — тест-кейсы ручного тестирования")
    title.font = Font(bold=True, size=14, color="1F4E78")
    note = ws.cell(
        row=2,
        column=1,
        value="Как пользоваться: открой лист модуля, выполни шаги кейса на тестовом стенде, "
              "в «Комментарий» допиши фактический результат, ссылку на баг или доказательство "
              "и поставь «Статус» из выпадающего списка. Статистика ниже пересчитается сама.",
    )
    note.font = Font(italic=True, size=10, color="595959")
    note.alignment = Alignment(wrap_text=True, vertical="top")
    ws.merge_cells("A2:G2")
    ws.row_dimensions[2].height = 40
    warn = ws.cell(
        row=3,
        column=1,
        value="Все проверки — только на тестовом стенде (staging). Учётные данные и токены — в .env, "
              "в этот файл их не вписываем. Названия кнопок даны по-русски, в скобках — узбекский "
              "вариант интерфейса. Начало «Комментария» содержит теги: web — браузер, api — запрос "
              "(curl/Postman), positive/negative/boundary и другие — тип сценария. "
              "{STAGE_API_URL} в командах замени на адрес бэкенда тестового стенда из .env.",
    )
    warn.font = Font(italic=True, size=10, color="9C0006")
    warn.alignment = Alignment(wrap_text=True, vertical="top")
    ws.merge_cells("A3:G3")
    ws.row_dimensions[3].height = 40

    header_row = 5
    headers = ["Модуль", "Кейсов", "Passed", "Failed", "Blocked", "Not Run", "% пройдено"]
    for col_idx, header in enumerate(headers, start=1):
        cell = ws.cell(row=header_row, column=col_idx, value=header)
        cell.font = HEADER_FONT
        cell.fill = HEADER_FILL
        cell.alignment = Alignment(horizontal="center", vertical="center")

    main_modules = [
        m
        for m in MODULES
        if not m.get("deferred", m["sheet"].startswith(DEFERRED_SHEET_PREFIX))
    ]
    deferred_modules = [
        m
        for m in MODULES
        if m.get("deferred", m["sheet"].startswith(DEFERRED_SHEET_PREFIX))
    ]

    row = header_row + 1
    first_data_row = row
    for module in main_modules:
        sheet = module["sheet"]
        n = len(module["cases"])
        ref = f"'{sheet}'!${STATUS_COL}$2:${STATUS_COL}${n + 1}"
        ws.cell(row=row, column=1, value=sheet)
        ws.cell(row=row, column=2, value=n)
        ws.cell(row=row, column=3, value=f'=COUNTIF({ref},"Passed")')
        ws.cell(row=row, column=4, value=f'=COUNTIF({ref},"Failed")')
        ws.cell(row=row, column=5, value=f'=COUNTIF({ref},"Blocked")')
        ws.cell(row=row, column=6, value=f'=COUNTIF({ref},"Not Run")')
        pct = ws.cell(row=row, column=7, value=f"=IF(B{row}=0,0,C{row}/B{row})")
        pct.number_format = "0%"
        for col_idx in range(1, 8):
            ws.cell(row=row, column=col_idx).border = THIN_BORDER
        row += 1

    total_row = row
    ws.cell(row=total_row, column=1, value="ИТОГО (без отложенных)").font = Font(bold=True)
    for col_idx, letter in ((2, "B"), (3, "C"), (4, "D"), (5, "E"), (6, "F")):
        c = ws.cell(
            row=total_row,
            column=col_idx,
            value=f"=SUM({letter}{first_data_row}:{letter}{total_row - 1})",
        )
        c.font = Font(bold=True)
    pct = ws.cell(row=total_row, column=7, value=f"=IF(B{total_row}=0,0,C{total_row}/B{total_row})")
    pct.number_format = "0%"
    pct.font = Font(bold=True)
    for col_idx in range(1, 8):
        ws.cell(row=total_row, column=col_idx).border = THIN_BORDER
        ws.cell(row=total_row, column=col_idx).fill = PatternFill("solid", fgColor="E8EDFB")

    # Отложенные — отдельной строкой, вне общего процента
    if deferred_modules:
        row = total_row + 2
        label = ws.cell(row=row, column=1, value="Вне общей статистики (ждут релиза):")
        label.font = Font(italic=True, size=10, color="595959")
        row += 1
        for module in deferred_modules:
            sheet = module["sheet"]
            n = len(module["cases"])
            ref = f"'{sheet}'!${STATUS_COL}$2:${STATUS_COL}${n + 1}"
            ws.cell(row=row, column=1, value=sheet)
            ws.cell(row=row, column=2, value=n)
            ws.cell(row=row, column=3, value=f'=COUNTIF({ref},"Passed")')
            ws.cell(row=row, column=4, value=f'=COUNTIF({ref},"Failed")')
            ws.cell(row=row, column=5, value=f'=COUNTIF({ref},"Blocked")')
            ws.cell(row=row, column=6, value=f'=COUNTIF({ref},"Not Run")')
            ws.cell(row=row, column=7, value="—").alignment = Alignment(horizontal="center")
            for col_idx in range(1, 8):
                ws.cell(row=row, column=col_idx).border = THIN_BORDER
                ws.cell(row=row, column=col_idx).font = Font(italic=True, color="595959")
            row += 1

    row += 2
    risk_title = ws.cell(row=row, column=1, value="Сверка рисков R-1…R-10 → тест-кейсы")
    risk_title.font = Font(bold=True, size=12, color="1F4E78")
    ws.merge_cells(start_row=row, start_column=1, end_row=row, end_column=7)
    row += 1

    for start_col, end_col, value in (
        (1, 1, "Риск"),
        (2, 4, "Что проверяем"),
        (5, 7, "Покрывающие кейсы"),
    ):
        cell = ws.cell(row=row, column=start_col, value=value)
        cell.font = HEADER_FONT
        cell.fill = HEADER_FILL
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
        if end_col > start_col:
            ws.merge_cells(start_row=row, start_column=start_col, end_row=row, end_column=end_col)
    for col_idx in range(1, 8):
        ws.cell(row=row, column=col_idx).border = THIN_BORDER
    row += 1

    for risk_id, risk_name, case_ids in RISK_COVERAGE:
        ws.cell(row=row, column=1, value=risk_id).alignment = Alignment(
            horizontal="center", vertical="top"
        )
        ws.cell(row=row, column=2, value=risk_name)
        ws.merge_cells(start_row=row, start_column=2, end_row=row, end_column=4)
        ws.cell(row=row, column=5, value=case_ids)
        ws.merge_cells(start_row=row, start_column=5, end_row=row, end_column=7)
        for col_idx in range(1, 8):
            cell = ws.cell(row=row, column=col_idx)
            cell.border = THIN_BORDER
            cell.alignment = Alignment(vertical="top", wrap_text=True)
        ws.row_dimensions[row].height = 32
        row += 1

    row += 1
    gate_title = ws.cell(row=row, column=1, value="Критерий допуска клиентов (Release Gate)")
    gate_title.font = Font(bold=True, size=12, color="1F4E78")
    ws.merge_cells(start_row=row, start_column=1, end_row=row, end_column=7)
    row += 1

    release_gates = [
        ("1", "Все активные кейсы выполнены", "В общей статистике Not Run = 0 и Blocked = 0"),
        ("2", "Критичные и высокие проверки успешны", "Все active Critical/High = Passed; Failed = 0"),
        ("3", "Нет релизных дефектов", "Нет открытых P0/P1; P2 имеет письменное решение владельца продукта"),
        ("4", "Пройдены клиентские сквозные пути", "TC-396, TC-397 и TC-398 = Passed"),
        ("5", "Пройдена эксплуатационная приёмка", "TC-373–TC-375, TC-380–TC-384 и TC-399–TC-400 = Passed"),
        ("6", "Закрыты расхождения диаграмм", "TC-351, TC-352, TC-354 = Passed"),
        ("7", "Будущие функции не выданы как готовые", "Отложенные кейсы исключены из релиза или функция отдельно принята"),
    ]
    for number, condition, evidence in release_gates:
        ws.cell(row=row, column=1, value=number).alignment = Alignment(
            horizontal="center", vertical="top"
        )
        ws.cell(row=row, column=2, value=condition)
        ws.merge_cells(start_row=row, start_column=2, end_row=row, end_column=4)
        ws.cell(row=row, column=5, value=evidence)
        ws.merge_cells(start_row=row, start_column=5, end_row=row, end_column=7)
        for col_idx in range(1, 8):
            cell = ws.cell(row=row, column=col_idx)
            cell.border = THIN_BORDER
            cell.alignment = Alignment(vertical="top", wrap_text=True)
        ws.row_dimensions[row].height = 34
        row += 1

    row += 1
    disclaimer = ws.cell(
        row=row,
        column=1,
        value="Важно: прохождение набора не доказывает абсолютное отсутствие дефектов. Оно подтверждает, "
              "что все известные требования, критические риски и клиентские сценарии проверены на указанной "
              "версии и окружении с зафиксированными доказательствами.",
    )
    disclaimer.font = Font(italic=True, size=10, color="9C0006")
    disclaimer.alignment = Alignment(wrap_text=True, vertical="top")
    ws.merge_cells(start_row=row, start_column=1, end_row=row, end_column=7)
    ws.row_dimensions[row].height = 40
    ws.sheet_properties.tabColor = "DDEBF7"

    return ws


def main():
    preserved = read_existing_results(TARGET_FILE)
    if preserved:
        default_statuses = {
            case["id"]: case.get("status", DEFAULT_STATUS)
            for module in MODULES
            for case in module["cases"]
        }
        default_comments = {
            case["id"]: default_comment(case)
            for module in MODULES
            for case in module["cases"]
        }
        filled = sum(
            1
            for case_id, saved in preserved.items()
            if (saved.get("fact") and str(saved["fact"]).strip())
            or (
                saved.get("comment")
                and str(saved["comment"]).strip()
                != default_comments.get(case_id, "")
            )
            or (
                saved.get("automation")
                and str(saved["automation"]).strip() not in ("", "—")
            )
            or (
                saved.get("status")
                and str(saved["status"]).strip()
                not in ("", default_statuses.get(case_id, DEFAULT_STATUS))
            )
        )
        print(f"Найден существующий файл: сохранено ручных результатов — {filled} "
              f"(всего кейсов в старом файле: {len(preserved)})")

    wb = openpyxl.Workbook()
    wb.remove(wb.active)  # убираем пустой лист по умолчанию

    for module in MODULES:
        build_module_sheet(wb, module, preserved)

    build_summary(wb)
    build_progress_sheet(wb)

    wb.calculation.calcMode = "auto"
    wb.calculation.fullCalcOnLoad = True
    wb.calculation.forceFullCalc = True

    # Проверка сквозной нумерации и уникальности ID
    seen = set()
    ordered_ids = []
    for module in MODULES:
        for case in module["cases"]:
            assert case["id"] not in seen, f"Дубль ID: {case['id']}"
            seen.add(case["id"])
            ordered_ids.append(case["id"])
    expected_ids = [f"TC-{number:03d}" for number in range(1, len(ordered_ids) + 1)]
    assert ordered_ids == expected_ids, "ID кейсов должны идти подряд в порядке листов"

    wb.save(TARGET_FILE)
    total = sum(len(m["cases"]) for m in MODULES)
    print(f"Готово: {TARGET_FILE}")
    print(f"Листов-модулей: {len(MODULES)}, кейсов всего: {total}")


if __name__ == "__main__":
    main()
